def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Early cooperation phase
    if n < 10:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_defects = 0
    for a in opp:
        if a == 'D':
            opp_defects += 1

    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # If opponent never defected, keep cooperating
    if opp_defects == 0:
        return 'C'

    # Compute recent cooperation rate over last 10 rounds
    window = 10
    if n < window:
        window = n
    recent_opp = opp[-window:]
    recent_c = 0
    for a in recent_opp:
        if a == 'C':
            recent_c += 1
    recent_opp_rate = recent_c / window

    # If opponent is defecting heavily, defect mostly
    if opp_defects >= n * 0.6 or recent_opp_rate <= 0.3:
        if n % 11 == 0:
            return 'C'
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    if last_opp == 'C':
        return 'C'

    # Opponent defected last round
    my_recent_def = False
    if n >= 1 and me[-1] == 'D':
        my_recent_def = True
    elif n >= 2 and me[-2] == 'D':
        my_recent_def = True

    if my_recent_def:
        return 'C'

    # If opponent rarely defects, punish once then forgive
    if opp_defects <= n * 0.15:
        return 'D'

    # Otherwise, retaliate
    return 'D'
